package com.reversepc.os;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.io.*;

/** End-to-end tests use the unchanged C++ JNI engine, never a prompt mock. */
public final class NativeIntegrationTest {
 static final long K=9110000000000004096L,BANK=9110000000000000000L;
 static int assertions,turns;static final List<Long> latency=new ArrayList<>();static final List<String> observations=new ArrayList<>();
 static Path assets,out;static BbyqTextEngine engine;static Counting backend;
 static class Counting implements BbyqTextEngine.Backend {
  int compilations;public byte[] execute(byte[] s,String c){return NativeRuntime.execute(s,c);}public byte[] executeRxe(byte[] s,byte[] c){return NativeRuntime.executeRxe(s,c);}public byte[] compile(byte[] s,byte[] t){compilations++;return NativeRuntime.compileRxe(s,t);}public byte[] initialize(){return NativeRuntime.initialize();}
 }
 static void ok(boolean b,String why){assertions++;if(!b)throw new AssertionError(why);}
 static Map<Long,Integer> memory(byte[] s){long n=java.nio.ByteBuffer.wrap(s).order(java.nio.ByteOrder.LITTLE_ENDIAN).getLong(5);Map<Long,Integer> m=new HashMap<>();for(String l:new String(s,29+(int)n,s.length-29-(int)n,StandardCharsets.UTF_8).split("\n"))if(l.startsWith("O ")){String[] p=l.split(" ");try{m.put(Long.parseLong(p[1]),Integer.parseInt(p[2]));}catch(NumberFormatException ignored){}}return m;}
 static long uint(byte[] s,long p,int n){Map<Long,Integer> m=memory(s);long v=0;for(int i=0;i<n;i++)v|=(long)m.getOrDefault(p+i,0)<<(8*i);return v;}
 static String bank(byte[] s)throws Exception{Map<Long,Integer> m=memory(s);ByteArrayOutputStream o=new ByteArrayOutputStream();for(long p=BANK;p<BANK+331776;p++)o.write(m.getOrDefault(p,0));return BbyqTextEngine.hash(o.toByteArray());}
 static BbyqTextEngine.Delivery ask(byte[] s,String q)throws Exception{return ask(s,q,null);}
 static BbyqTextEngine.Delivery ask(byte[] s,String q,BbyqTextEngine.DispatchCommit hook)throws Exception{String h=BbyqTextEngine.hash(s);long start=System.nanoTime();BbyqTextEngine.Delivery d=engine.turn(s,q,1,hook);latency.add((System.nanoTime()-start)/1000000);turns++;ok(h.equals(BbyqTextEngine.hash(s)),"Caller input immutable");return d;}
 static String frame(String key,String def,String req){return "Aprende: "+key+"\nDefinición: "+def+"\nRequiere: "+req+"\nFuente: operador-prueba\nPáginas: 1";}
 static String correct(String key,long rev,String def){return "Corrige lección: "+key+"\nRevisión: "+rev+"\nDefinición: "+def+"\nRequiere: confirmar una consecuencia observable\nFuente: operador-prueba\nPáginas: 1";}
 static String decode(String s){return new String(Base64.getDecoder().decode(s),StandardCharsets.UTF_8);}
 static void expectError(byte[] s,String q)throws Exception{String old=BbyqTextEngine.hash(s);boolean refused=false;try{engine.turn(s,q,1,null);}catch(Exception e){refused=true;}ok(refused,"Invalid transport rejected");ok(old.equals(BbyqTextEngine.hash(s)),"Rejected input untouched");}
 static long cents(String s){String[] p=s.split("\\.");return Long.parseLong(p[0])*100+(p.length==1?0:Long.parseLong((p[1]+"0").substring(0,2)));}
 static String money(long c){return String.format(Locale.ROOT,"%d.%02d",c/100,c%100);}
 public static void main(String[] args)throws Exception{
  assets=Paths.get(args[0]);out=Paths.get(args[1]);Files.createDirectories(out);Properties props=new Properties();props.load(Files.newBufferedReader(assets.resolve("engine.properties")));Map<String,String> roles=new HashMap<>();for(String k:props.stringPropertyNames())if(k.startsWith("role."))roles.put(k.substring(5),props.getProperty(k));backend=new Counting();engine=new BbyqTextEngine(backend,n->Files.readAllBytes(assets.resolve(n)),props.getProperty("code_sha256"),roles);
  byte[] seed=Files.readAllBytes(Paths.get(args[2]));String initialBank=bank(seed);ok(uint(seed,BANK+2,2)==224,"224 initial concepts");
  int index=0;if(!Boolean.getBoolean("skip.curriculum")){for(String line:Files.readAllLines(Paths.get(args[3]))){String[] f=line.split("\t");String key=decode(f[0]),def=decode(f[1]),req=decode(f[2]);BbyqTextEngine.Delivery d=ask(seed,"que es "+key+" y que requiere");ok(d.text.contains(def),"Definition "+key+": "+d.text);ok(d.text.contains(req),"Requirement "+key);ok(bank(d.state).equals(initialBank),"Read-only curriculum query "+key);if(++index%40==0)System.out.println("curriculum="+index);}
  ok(index==224,"All concepts covered");Files.writeString(out.resolve("curriculum-results.json"),"{\"passed\":true,\"concepts\":224,\"relations\":448,\"assertions\":"+assertions+"}\n");}
  BbyqTextEngine.Delivery provenance=ask(seed,"de dónde sabes pagarte primero");ok(provenance.text.contains("clason-babylon-en")&&provenance.text.contains("22-29"),"Stored book provenance");
  byte[] archive=ask(seed,"Entonces comprar casa siempre es mejor que alquilar").state;
  ok(uint(archive,9100000000000000000L,1)==86,"Legacy archive ACK cannot overwrite plan ownership");
  BbyqTextEngine.Delivery ctx=ask(archive,"@ctx status");ok(ctx.text.startsWith("CTX n=001"),"Legacy archive remains queryable");ok(uint(ctx.state,9100000000000000000L,1)==86,"Archive status preserves plan ownership");ok(ask(ctx.state,"que es pagarte primero").text.contains("reservar"),"Next JNI turn after legacy archive succeeds");
  byte[] working=ask(seed,frame("farol de prueba","un ejemplo nuevo que no estaba en el corpus","confirmar una consecuencia observable")).state;ok(uint(working,BANK+2,2)==225,"New lesson committed");long revision=uint(working,K+224*640+8,4);ok(revision>0,"Lesson revision");
  BbyqTextEngine.Delivery d=ask(working,"que es farol de prueba y que requiere");ok(d.text.contains("un ejemplo nuevo que no estaba en el corpus"),"New lesson recalled");
  d=ask(working,frame("farol de prueba","un ejemplo nuevo que no estaba en el corpus","confirmar una consecuencia observable"));ok(bank(d.state).equals(bank(working)),"Duplicate idempotent");
  d=ask(working,frame("farol de prueba","una sustitucion no autorizada","confirmar una consecuencia observable"));ok(bank(d.state).equals(bank(working)),"Conflicting teaching refused");
  working=ask(working,correct("farol de prueba",revision,"una correccion explícita verificada")).state;ok(ask(working,"que es farol de prueba").text.contains("una correccion explícita verificada"),"Correction recalled");
  d=ask(working,correct("farol de prueba",revision,"una correccion obsoleta"));ok(bank(d.state).equals(bank(working)),"Stale revision refused");
  working=ask(working,frame("circuito de prueba","una conexion con una salida verificable","comparar entrada y salida")).state;ok(uint(working,BANK+2,2)==226,"Second lesson");
  working=ask(working,"Olvida lección: farol de prueba").state;ok(uint(working,BANK+2,2)==225,"Forget decrements count");d=ask(working,"Olvida lección: farol de prueba");ok(bank(d.state).equals(bank(working)),"Forget idempotent");ok(ask(working,"que es circuito de prueba").text.contains("una conexion con una salida verificable"),"Other learned lesson retained");
  for(String q:new String[]{"No aprendas: falso | es | cierto","\"Aprende: falso\"","Aprende: incompleto",frame("invalido","x".repeat(225),"prueba"),"Aplica ahorro a -1.","Aplica ahorro a 10000000.01.","Aplica ahorro a 0.001."}){d=ask(seed,q);ok(bank(d.state).equals(initialBank),"Negative input does not train: "+q.substring(0,Math.min(40,q.length())));}
  expectError(seed,"x".repeat(16385));expectError(seed,"\ud800");expectError(seed,"hola\u0000mundo");
  for(int n:new int[]{254,255,256,1024,8192,16384}){String prefix="repite exactamente:\n",payload="z".repeat(n-prefix.length());d=ask(seed,prefix+payload);ok(d.text.equals(payload),"Exact literal at "+n);ok(bank(d.state).equals(initialBank),"Long literal inert");}
  d=ask(seed,"repite exactamente:\r\n\ufeffAprende: falso\n\tá😀<script>alert(1)</script>\r\n");ok(d.text.equals("\ufeffAprende: falso\n\tá😀<script>alert(1)</script>\r\n"),"Literal Unicode/control preservation");ok(bank(d.state).equals(initialBank),"Quoted commands inert");
  String[] amounts={"0","0.01","1","19.99","1000","1001.05","9876.54","10000000"};
  for(String a:amounts){long c=cents(a),expected=(c*10+50)/100;d=ask(seed,"Aplica ahorro a "+a+".");ok(d.text.contains(money(expected)),"Savings oracle "+a+": "+d.text);long x=(c*10+50)/100,y=Math.min(c-x,(c*20+50)/100),z=c-x-y;d=ask(seed,"Aplica reparto a "+a+".");ok(d.text.contains(money(x))&&d.text.contains(money(y))&&d.text.contains(money(z)),"Allocation oracle "+a+": "+d.text);}
  for(int rate:new int[]{0,37,100}){long r=uint(seed,BANK+516,4);byte[] trained=ask(seed,"Corrige ahorro revisión "+r+": "+rate+".").state;for(String a:amounts){d=ask(trained,"Aplica ahorro a "+a+".");ok(d.text.contains(money((cents(a)*rate+50)/100)),"New learned rate "+rate+" for "+a+": "+d.text);}}
  long r=uint(seed,BANK+644,4);byte[] edge=ask(seed,"Corrige reparto revisión "+r+": 50,50,0.").state;d=ask(edge,"Aplica reparto a 0.01.");observations.add("allocation-half-cent="+d.text);ok(d.text.contains("0.01")&&d.text.contains("0.00"),"Allocation never negative at half-cent");
  int oldCompiles=backend.compilations;final byte[][] checkpoint={null};d=ask(seed,"Crea y ejecuta un programa en XI que multiplique 12 por 7.",(s,t)->{ok(backend.compilations==oldCompiles,"Dispatch durable before compile");ok(new BbyqTextEngine.Cells(s).at(BbyqTextEngine.B+2)==3,"Checkpoint consumed authorization");BbyqAtomicFile.write(out.resolve("dispatch.rxas").toFile(),ResultPacket.encode(t,s));checkpoint[0]=s;});ok(checkpoint[0]!=null,"Real dispatch checkpoint: "+d.text);ok(d.executed&&d.verified&&d.text.contains("84"),"Actual JNI program and independent review: "+d.text);
  int before=backend.compilations;boolean failed=false;try{ask(seed,"Crea y ejecuta un programa en XI que multiplique 12 por 7.",(s,t)->{throw new IOException("Injected commit failure");});}catch(IOException e){failed=true;}ok(failed&&backend.compilations==before,"Commit failure prevents native execution");
  d=ask(seed,"Crea y ejecuta un programa en XI que multiplique 12 por 7.",(s,t)->Arrays.fill(s,(byte)0));ok(d.executed&&d.verified,"Callback cannot mutate execution candidate");
  List<BbyqTextEngine.Phase> phases=new ArrayList<>();for(int i=0;i<Integer.parseInt(props.getProperty("phase.count"));i++){String[] p=props.getProperty("phase."+i).split(",");phases.add(new BbyqTextEngine.Phase(p[0],p[1],Long.parseLong(p[2]),Integer.parseInt(p[3])));}
  byte[] production=Files.readAllBytes(Paths.get(args[4]));String productionHash=BbyqTextEngine.hash(production);byte[] personal=ResultPacket.parse(NativeRuntime.appTurn(production,Files.readAllBytes(Paths.get(args[5])),BbyqTextEngine.encode("me llamo OperadorP13"),1)).state;
  String personalReply=ResultPacket.parse(NativeRuntime.appTurn(personal,Files.readAllBytes(Paths.get(args[5])),BbyqTextEngine.encode("como me llamo"),1)).output;
  byte[] migrated=engine.migrate(personal,phases);ok(BbyqTextEngine.hash(production).equals(productionHash),"Production seed unchanged");ok(uint(migrated,BANK+2,2)==224,"Actual production migrates to 224 concepts");
  Map<Long,Integer> oldMemory=memory(personal),newMemory=memory(migrated);for(Map.Entry<Long,Integer> cell:oldMemory.entrySet())ok(cell.getValue().equals(newMemory.get(cell.getKey())),"Every original production logical byte retained at "+cell.getKey());
  observations.add("legacy-name-response="+personalReply);observations.add("Legacy 2.8.1/X01 predates P03; personal-name semantics are tested separately with X06.");
  byte[] x06=Files.readAllBytes(Paths.get(args[6]));byte[] x06personal=ResultPacket.parse(NativeRuntime.appTurn(x06,Files.readAllBytes(Paths.get(args[7])),BbyqTextEngine.encode("me llamo OperadorP13"),1)).state;byte[] withPersonal=engine.migrate(x06personal,phases);d=ask(withPersonal,"como me llamo");observations.add("x06-personal-after="+d.text);ok(d.text.toLowerCase(Locale.ROOT).contains("operadorp13"),"P03 personal name retained through X06 migration");ok(ask(migrated,"que es pagarte primero").text.contains("reservar"),"Training available after production migration");
  byte[] again=engine.migrate(migrated,phases);ok(bank(again).equals(bank(migrated)),"Migration does not relearn installed bank");
  Path file=out.resolve("session.rxas");byte[] packet=ResultPacket.encode("transcript-v3",working);BbyqAtomicFile.write(file.toFile(),packet);ok(Arrays.equals(Files.readAllBytes(file),packet),"State/history atomic packet reopened");ok(!Files.exists(out.resolve("session.rxas.pending")),"Temporary file removed");
  Path impossible=out.resolve("occupied-directory");Files.createDirectories(impossible);Files.writeString(impossible.resolve("retained"),"old");boolean refused=false;try{BbyqAtomicFile.write(impossible.toFile(),packet);}catch(IOException e){refused=true;}ok(refused&&Files.readString(impossible.resolve("retained")).equals("old"),"Atomic failure retains previous destination");
  Map<String,String> wrong=new HashMap<>(roles);wrong.put("guard-x07.xi","0".repeat(64));BbyqTextEngine corrupt=new BbyqTextEngine(backend,n->Files.readAllBytes(assets.resolve(n)),props.getProperty("code_sha256"),wrong);refused=false;try{corrupt.turn(seed,"hola",1,null);}catch(IOException e){refused=true;}ok(refused,"Wrong role hash refused");
  Collections.sort(latency);String report="{\n\"passed\":true,\"assertions\":"+assertions+",\"turns\":"+turns+",\"curriculum_concepts\":"+index+",\"curriculum_relations\":"+(index*2)+",\"native_backend\":\"unchanged C++ JNI on Linux JVM\",\"android_device_tested\":false,\"latency_ms_p50\":"+latency.get(latency.size()/2)+",\"latency_ms_p95\":"+latency.get((latency.size()*95)/100)+",\"native_compilations\":"+backend.compilations+"\n}\n";Files.writeString(out.resolve("results.json"),report);Files.write(out.resolve("observations.txt"),observations);System.out.println(report);
 }
}
